mapper.select:
SELECT
id, parent_id, permission_name, permission_key, sort, create_time, update_time
FROM
sys_permission


        AND permission_name LIKE CONCAT('%', #{permissionName}, '%')


        AND permission_key LIKE CONCAT('%', #{permissionKey}, '%')


        AND parent_id = #{parentId}




                AND create_time >= #{startTime}


                AND create_time <= #{endTime}


                AND create_time BETWEEN #{startTime} AND #{endTime}





    ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}


    ORDER BY create_time DESC

WITH RECURSIVE permission_children AS ( SELECT id, parent_id, permission_name, permission_key, sort, create_time, update_time FROM sys_permission WHERE id = #{id}
UNION ALL
SELECT p.id, p.parent_id, p.permission_name, p.permission_key, p.sort, p.create_time, p.update_time FROM sys_permission p INNER JOIN permission_children pc ON p.parent_id = pc.id ) SELECT id, parent_id, permission_name, permission_key, sort, create_time, update_time FROM permission_children ORDER BY sort ASC

mapper.delete:
WITH RECURSIVE permission_children AS (SELECT id, parent_id, permission_name, permission_key FROM sys_permission WHERE parent_id = #{id}
UNION ALL
SELECT p.id, p.parent_id, p.permission_name, p.permission_key FROM sys_permission p INNER JOIN permission_children pc ON p.parent_id = pc.id) DELETE FROM sys_permission WHERE id IN (SELECT id FROM permission_children)
